"""Hosted projections over native Session, Attempt and scheduled-research records."""

import logging
import os
import re
import sys

from fastapi import Depends, FastAPI, HTTPException
from src.api.security import require_auth

logger = logging.getLogger(__name__)
_SYMBOL = re.compile(r"^[0-9]{6}\.(SH|SZ|BJ)$")
_TASKS = {"comprehensive", "fundamental", "technical", "risk"}
_MODES = {"ultrashort", "swing", "medium"}
_ATTEMPT_FIELDS = (
    "attempt_id", "session_id", "parent_attempt_id", "status", "summary", "error",
    "created_at", "started_at", "completed_at", "metrics",
)


def workbench_context(config):
    value = config.get("mona_workbench") if isinstance(config, dict) else None
    if (not isinstance(value, dict) or set(value) != {"symbol", "task", "mode"}
        or not isinstance(value.get("symbol"), str) or not _SYMBOL.fullmatch(value["symbol"])
        or value.get("task") not in _TASKS or value.get("mode") not in _MODES):
        return None
    return dict(value)


def _attempt(attempt):
    data = attempt.to_dict()
    return {key: data.get(key) for key in _ATTEMPT_FIELDS}


def session_projection(store, symbol):
    sessions = [session for session in store.list_sessions(limit=sys.maxsize)
                if (workbench_context(session.config) or {}).get("symbol") == symbol]
    by_id = {session.session_id: session for session in sessions}
    attempts = {attempt.attempt_id: attempt for attempt in store.list_attempts()
                if attempt.session_id in by_id}
    rows = []
    for session in sessions[:100]:
        context = workbench_context(session.config)
        attempt = attempts.get(session.last_attempt_id)
        if attempt is not None and attempt.session_id != session.session_id:
            attempt = None
        rows.append({
            "session_id": session.session_id, "title": session.title,
            "task": context["task"], "mode": context["mode"],
            "status": session.status.value, "last_attempt_id": session.last_attempt_id,
            "created_at": session.created_at, "updated_at": session.updated_at,
            "attempt": _attempt(attempt) if attempt is not None else None,
        })
    completed = [attempt for attempt in attempts.values()
                 if attempt.status.value == "completed" and attempt.summary and attempt.completed_at]
    latest = max(completed, key=lambda attempt: attempt.completed_at) if completed else None
    report = None
    if latest is not None:
        context = workbench_context(by_id[latest.session_id].config)
        report = {**_attempt(latest), "task": context["task"], "mode": context["mode"],
                  "as_of": latest.completed_at}
    return rows, report


def scheduled_projection(store, symbol):
    from src.api.scheduled_routes import _job_to_response

    jobs = [job for job in store.load().values()
            if (workbench_context(job.config) or {}).get("symbol") == symbol]
    jobs.sort(key=lambda job: job.created_at, reverse=True)
    return [_job_to_response(job).model_dump() for job in jobs[:100]]


def register_mona_workbench(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    @app.get("/mona/workbench", dependencies=[Depends(require_auth)])
    def get_workbench(symbol: str):
        if not _SYMBOL.fullmatch(symbol):
            raise HTTPException(status_code=422, detail="Invalid stock symbol")
        result = {"symbol": symbol, "sessions": [], "latest_report": None,
                  "scheduled_jobs": [], "scheduler": None, "errors": []}
        try:
            host = sys.modules.get("api_server") or sys.modules.get("agent.api_server")
            service = host._get_session_service() if host is not None else None
            if service is None:
                raise RuntimeError("Session runtime unavailable")
            result["sessions"], result["latest_report"] = session_projection(service.store, symbol)
        except (OSError, ValueError, TypeError, KeyError, RuntimeError) as exc:
            result["errors"].append({"section": "sessions", "code": "read_failed"})
            logger.warning("Workbench sessions read failed: %s", type(exc).__name__)
        try:
            from src.api.scheduled_routes import _get_scheduled_research_store

            result["scheduled_jobs"] = scheduled_projection(_get_scheduled_research_store(), symbol)
        except (OSError, ValueError, TypeError, KeyError, RuntimeError) as exc:
            result["errors"].append({"section": "scheduled", "code": "read_failed"})
            logger.warning("Workbench schedules read failed: %s", type(exc).__name__)
        try:
            from src.scheduled_research.service import scheduler_status

            result["scheduler"] = scheduler_status()
        except (OSError, ValueError, TypeError, KeyError, RuntimeError) as exc:
            result["errors"].append({"section": "scheduler", "code": "read_failed"})
            logger.warning("Workbench scheduler read failed: %s", type(exc).__name__)
        return result
